func formatTimeAgo(t time.Time) string {
	d := time.Since(t)
	switch {
	case d < time.Minute:
		return "just now"
	case d < time.Hour:
		m := int(d.Minutes())
		if m == 1 {
			return "1 min ago"
		}
		return fmt.Sprintf("%d min ago", m)
	case d < 24*time.Hour:
		h := int(d.Hours())
		if h == 1 {
			return "1 hour ago"
		}
		return fmt.Sprintf("%d hours ago", h)
	case d < 30*24*time.Hour:
		days := int(d.Hours() / 24)
		if days == 1 {
			return "yesterday"
		}
		return fmt.Sprintf("%d days ago", days)
	default:
		return t.Format("Jan 2, 2006")
	}
}

func stitchSegmentCount(segments []byte) int {
	count := 0
	depth := 0
	for _, b := range segments {
		if b == '[' || b == '{' {
			depth++
		} else if b == ']' || b == '}' {
			depth--
		} else if b == ',' && depth == 1 {
			count++
		}
	}
	if depth == 0 && len(segments) > 2 {
		count++
	}
	return count
}

